#!/usr/bin/env python3
"""
A compact, original reimplementation of the observed Shellharden CLI behavior.
It implements the documented high-level modes and the core quoting rewrites
inferred from black-box interaction with the supplied executable.
"""
import os
import re
import sys
import difflib
from dataclasses import dataclass

VERSION = "4.3.1"

HELP = """Shellharden: The corrective bash syntax highlighter.

Usage:
	shellharden [options] [files]
	cat files | shellharden [options] ''

Shellharden is a syntax highlighter and a tool to semi-automate the rewriting
of scripts to ShellCheck conformance, mainly focused on quoting.

The default mode of operation is like `cat`, but with syntax highlighting in
foreground colors and suggestive changes in background colors.

Options:
	--suggest         Output a colored diff suggesting changes.
	--syntax          Output syntax highlighting with ANSI colors.
	--syntax-suggest  Diff with syntax highlighting (default mode).
	--transform       Output suggested changes.
	--check           No output; exit with 2 if changes are suggested.
	--replace         Replace file contents with suggested changes.
	--                Don't treat further arguments as options.
	-h|--help         Show help text.
	--version         Show version.

The changes suggested by Shellharden inhibits word splitting and indirect
pathname expansion. This will make your script ShellCheck compliant in terms of
quoting. Whether your script will work afterwards is a different question:
If your script was using those features on purpose, it obviously won't anymore!

Every script is possible to write without using word splitting or indirect
pathname expansion, but it may involve doing things differently.
See the accompanying file how_to_do_things_safely_in_bash.md or online:
https://github.com/anordal/shellharden/blob/master/how_to_do_things_safely_in_bash.md
"""

RESET = "\x1b[m"
GREEN = "\x1b[0;42m"
RED_BG = "\x1b[0;41m"
CMD_C = "\x1b[0;38;2;192;0;128m"
VAR_C = "\x1b[0;38;2;63;127;207m"
DQ_C = "\x1b[0;38;2;255;0;0m"
SQ_C = "\x1b[0;38;2;255;204;85m"
COMMENT_C = "\x1b[0;1;3;38;2;120;144;96m"
KW_C = "\x1b[0;1m"
ASSIGN_C = "\x1b[0;38;2;0;127;255m"
DBR_C = "\x1b[0;38;2;192;0;192m"

IDENT_START = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_")
IDENT_TAIL = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_0123456789")
SAFE_NUMERIC_SPECIAL = set("?$!#")
RESERVED = {"if", "then", "else", "elif", "fi", "for", "select", "do", "done", "case", "in", "esac", "while", "until", "function", "time", "coproc"}
DECL_BUILTINS = {"export", "readonly", "local", "declare"}
SEPARATING_WORDS = {"then", "do", "else", "elif"}

class TransformError(Exception):
    def __init__(self, message, position=None, kind="generic"):
        super().__init__(message)
        self.message = message
        self.position = position
        self.kind = kind


def is_ident_start(c):
    return c in IDENT_START

def is_ident_tail(c):
    return c in IDENT_TAIL

def is_space_no_nl(c):
    return c in " \t\r\v\f"

def is_assignment_word(w):
    # Bash-like NAME=... or NAME+=... .  Keep it intentionally conservative.
    m = re.match(r'^([A-Za-z_][A-Za-z0-9_]*)(\+?=)', w, re.S)
    return bool(m)

def split_assignment(w):
    m = re.match(r'^([A-Za-z_][A-Za-z0-9_]*)(\+?=)', w, re.S)
    if not m:
        return None
    return w[:m.end()], w[m.end():]


def strip_heredoc_delim(word):
    """Remove the simple quoting used in here-doc delimiters."""
    out = []
    i = 0
    while i < len(word):
        c = word[i]
        if c in "'\"":
            q = c; i += 1
            while i < len(word) and word[i] != q:
                if q == '"' and word[i] == '\\' and i + 1 < len(word):
                    out.append(word[i+1]); i += 2
                else:
                    out.append(word[i]); i += 1
            if i < len(word): i += 1
        elif c == '\\' and i + 1 < len(word):
            out.append(word[i+1]); i += 2
        else:
            out.append(c); i += 1
    return ''.join(out)


def find_line_end(s, pos):
    j = s.find('\n', pos)
    return len(s) if j < 0 else j + 1


def find_heredocs_on_line(line):
    """Approximate scanner for here-doc operators on a single command line."""
    res = []
    i = 0
    while i < len(line):
        c = line[i]
        if c == '#':
            # comment if at beginning or after whitespace/control
            if i == 0 or line[i-1] in ' \t;|&()':
                break
            i += 1; continue
        if c == "'":
            j = line.find("'", i+1); i = len(line) if j < 0 else j+1; continue
        if c == '"':
            i = consume_double_quote(line, i); continue
        if c == '`':
            i = consume_backtick(line, i); continue
        if c == '$' and i + 1 < len(line):
            if line.startswith('$((', i):
                i = consume_arith(line, i); continue
            if line.startswith('$(', i):
                i = consume_dollar_paren(line, i); continue
            if line.startswith('${', i):
                i = consume_brace(line, i); continue
            if line.startswith("$'", i) or line.startswith('$"', i):
                q = line[i+1]; j = consume_quoted(line, i+1, q); i = j; continue
        if line.startswith('<<-', i) or (line.startswith('<<', i) and not line.startswith('<<<', i)):
            strip_tabs = line.startswith('<<-', i)
            i += 3 if strip_tabs else 2
            while i < len(line) and line[i] in ' \t': i += 1
            start = i
            # read one shell word as delimiter
            while i < len(line) and line[i] not in ' \t\r\n;|&<>':
                if line[i] in "'\"":
                    i = consume_quoted(line, i, line[i])
                elif line[i] == '\\' and i+1 < len(line):
                    i += 2
                else:
                    i += 1
            if i > start:
                res.append((strip_heredoc_delim(line[start:i]), strip_tabs))
            continue
        i += 1
    return res


def mask_heredocs(s):
    """Replace here-doc bodies with placeholders so parsers don't rewrite them."""
    pieces = []
    repl = {}
    pos = 0
    idx = 0
    line_start = 0
    pending = []
    n = len(s)
    while line_start < n:
        line_end = find_line_end(s, line_start)
        line = s[line_start:line_end]
        pieces.append(s[pos:line_end])
        pos = line_end
        hds = find_heredocs_on_line(line)
        if hds:
            body_start = line_end
            cur = line_end
            body_end = cur
            for delim, strip_tabs in hds:
                while cur < n:
                    le = find_line_end(s, cur)
                    txt = s[cur:le]
                    cmp = txt[:-1] if txt.endswith('\n') else txt
                    if cmp.endswith('\r'):
                        cmp2 = cmp[:-1]
                    else:
                        cmp2 = cmp
                    check = cmp2.lstrip('\t') if strip_tabs else cmp2
                    cur = le
                    if check == delim:
                        body_end = cur
                        break
                else:
                    body_end = n
            if body_end > body_start:
                marker = f"__SHELLHARDEN_HEREDOC_{idx}__"
                repl[marker] = s[body_start:body_end]
                pieces.append(marker)
                pos = body_end
                line_start = body_end
                idx += 1
                continue
        line_start = line_end
    pieces.append(s[pos:])
    return ''.join(pieces), repl


def unmask(s, repl):
    for k, v in repl.items():
        s = s.replace(k, v)
    return s

# ---------- consumers for balanced shell fragments ----------

def consume_quoted(s, i, q):
    # i points to the quote character (single or double).  For double quote,
    # skip nested expansions that can contain quotes.
    if q == '"':
        return consume_double_quote(s, i)
    i += 1
    while i < len(s):
        if s[i] == q:
            return i + 1
        i += 1
    raise TransformError("Unexpected end of file")


def consume_single_quote(s, i):
    return consume_quoted(s, i, "'")


def consume_double_quote(s, i):
    i += 1
    while i < len(s):
        c = s[i]
        if c == '"':
            return i + 1
        if c == '\\':
            i += 2 if i + 1 < len(s) else 1; continue
        if c == '`':
            i = consume_backtick(s, i); continue
        if c == '$' and i + 1 < len(s):
            if s.startswith('$((', i):
                i = consume_arith(s, i); continue
            if s.startswith('$(', i):
                i = consume_dollar_paren(s, i); continue
            if s.startswith('${', i):
                i = consume_brace(s, i); continue
            if s.startswith("$'", i) or s.startswith('$"', i):
                i = consume_quoted(s, i+1, s[i+1]); continue
        i += 1
    raise TransformError("Unexpected end of file")


def consume_backtick(s, i):
    i += 1
    while i < len(s):
        if s[i] == '\\' and i + 1 < len(s):
            i += 2; continue
        if s[i] == '`':
            return i + 1
        i += 1
    raise TransformError("Unexpected end of file")


def consume_brace(s, i):
    # i at ${
    i += 2
    depth = 1
    while i < len(s):
        c = s[i]
        if c == "'":
            i = consume_single_quote(s, i); continue
        if c == '"':
            i = consume_double_quote(s, i); continue
        if c == '`':
            i = consume_backtick(s, i); continue
        if c == '$' and i + 1 < len(s):
            if s.startswith('${', i):
                i = consume_brace(s, i); continue
            if s.startswith('$((', i):
                i = consume_arith(s, i); continue
            if s.startswith('$(', i):
                i = consume_dollar_paren(s, i); continue
        if c == '}':
            return i + 1
        i += 1
    raise TransformError("Unexpected end of file")


def consume_arith(s, i):
    # i at $(( ; consume through matching )) approximately.
    i += 3
    depth = 0
    while i < len(s):
        c = s[i]
        if c == "'":
            i = consume_single_quote(s, i); continue
        if c == '"':
            i = consume_double_quote(s, i); continue
        if c == '`':
            i = consume_backtick(s, i); continue
        if c == '$' and i + 1 < len(s):
            if s.startswith('$((', i):
                i = consume_arith(s, i); continue
            if s.startswith('$(', i):
                i = consume_dollar_paren(s, i); continue
            if s.startswith('${', i):
                i = consume_brace(s, i); continue
        if c == '(':
            depth += 1; i += 1; continue
        if c == ')':
            if depth == 0 and i + 1 < len(s) and s[i+1] == ')':
                return i + 2
            if depth > 0:
                depth -= 1
            i += 1; continue
        i += 1
    raise TransformError("Unexpected end of file")


def consume_dollar_paren(s, i):
    # i at $(, not arithmetic
    i += 2
    depth = 1
    while i < len(s):
        c = s[i]
        if c == "'":
            i = consume_single_quote(s, i); continue
        if c == '"':
            i = consume_double_quote(s, i); continue
        if c == '`':
            i = consume_backtick(s, i); continue
        if c == '$' and i + 1 < len(s):
            if s.startswith('$((', i):
                i = consume_arith(s, i); continue
            if s.startswith('$(', i):
                depth += 1; i += 2; continue
            if s.startswith('${', i):
                i = consume_brace(s, i); continue
            if s.startswith("$'", i) or s.startswith('$"', i):
                i = consume_quoted(s, i+1, s[i+1]); continue
        if (c == '<' or c == '>') and i + 1 < len(s) and s[i+1] == '(':
            i = consume_process_subst(s, i); continue
        if c == '(':
            depth += 1; i += 1; continue
        if c == ')':
            depth -= 1; i += 1
            if depth == 0:
                return i
            continue
        i += 1
    raise TransformError("Unexpected end of file")


def consume_process_subst(s, i):
    # i at <( or >(
    end = consume_dollar_paren('$' + s[i+1:], 0)  # parse as if $( ... )
    return i + end - 1


def consume_old_arith(s, i):
    # i at $[
    i += 2
    while i < len(s):
        c = s[i]
        if c == "'":
            i = consume_single_quote(s, i); continue
        if c == '"':
            i = consume_double_quote(s, i); continue
        if c == '`':
            i = consume_backtick(s, i); continue
        if c == '$' and i + 1 < len(s):
            if s.startswith('$((', i):
                i = consume_arith(s, i); continue
            if s.startswith('$(', i):
                i = consume_dollar_paren(s, i); continue
            if s.startswith('${', i):
                i = consume_brace(s, i); continue
        if c == ']':
            return i + 1
        i += 1
    raise TransformError("Unexpected end of file")

# ---------- expansion parsing/formatting ----------

@dataclass
class Expansion:
    kind: str
    raw: str
    end: int
    name: str = ''
    braced: bool = False
    content: str = ''
    safe_numeric: bool = False
    array: bool = False
    array_star: bool = False
    indirect: bool = False
    length: bool = False
    pitfall: bool = False


def parse_dollar(s, i):
    n = len(s)
    if i + 1 >= n or s[i] != '$':
        return None
    c = s[i+1]
    if c == '(':
        if i + 2 < n and s[i+2] == '(':
            end = consume_arith(s, i)
            return Expansion('arith', s[i:end], end)
        end = consume_dollar_paren(s, i)
        return Expansion('cmdsub', s[i:end], end, content=s[i+2:end-1])
    if c == '[':
        end = consume_old_arith(s, i)
        return Expansion('oldarith', s[i:end], end, content=s[i+2:end-1])
    if c == '{':
        end = consume_brace(s, i)
        content = s[i+2:end-1]
        exp = Expansion('param', s[i:end], end, braced=True, content=content)
        # classify simple/safe forms
        if content.startswith('#'):
            exp.length = True
            exp.safe_numeric = True
            return exp
        if content.startswith('!'):
            exp.indirect = True
            # Shellharden leaves these unquoted.
            return exp
        m = re.match(r'^([A-Za-z_][A-Za-z0-9_]*|[_@*?\-$!#]|[0-9]+)$', content)
        if m:
            exp.kind = 'simple'
            exp.name = content
            exp.safe_numeric = content in SAFE_NUMERIC_SPECIAL
            return exp
        m = re.match(r'^([A-Za-z_][A-Za-z0-9_]*)\[([@*])\]$', content)
        if m:
            exp.kind = 'array'
            exp.name = m.group(1)
            exp.array = True
            exp.array_star = (m.group(2) == '*')
            return exp
        return exp
    if c in "'\"":
        end = consume_quoted(s, i+1, c)
        return Expansion('dollarquote', s[i:end], end)
    if c == '$':
        return Expansion('simple', s[i:i+2], i+2, name='$', safe_numeric=True)
    if c in '?#!':
        return Expansion('simple', s[i:i+2], i+2, name=c, safe_numeric=True)
    if c in '*@-_':
        return Expansion('simple', s[i:i+2], i+2, name=c)
    if c.isdigit():
        j = i + 2
        if j < n and s[j].isdigit():
            # $10 pitfall: only one digit is actually the parameter.
            while j < n and s[j].isdigit():
                j += 1
            return Expansion('simple', s[i:j], j, name=s[i+1:j], pitfall=True)
        return Expansion('simple', s[i:i+2], i+2, name=c)
    if is_ident_start(c):
        j = i + 2
        while j < n and is_ident_tail(s[j]):
            j += 1
        return Expansion('simple', s[i:j], j, name=s[i+1:j])
    return None


def first_double_inner_char(raw, pos):
    if pos >= len(raw) or raw[pos] != '"':
        return ''
    j = pos + 1
    if j >= len(raw):
        return ''
    if raw[j] == '\\' and j + 1 < len(raw):
        return raw[j+1]
    return raw[j]


def simple_repr_in_quotes(exp, raw_word, end, eof=False):
    name = exp.name
    # $* is rewritten to "$@" when Shellharden inserts the quote.
    if not exp.braced and name == '*':
        return '$@'
    if exp.kind == 'array':
        # Unquoted ${arr[*]} is changed to ${arr[@]}.
        return '${%s[@]}' % exp.name
    if exp.kind == 'param':
        return exp.raw
    if exp.indirect or exp.length:
        return exp.raw
    if exp.safe_numeric:
        return exp.raw
    # Braced specials/digits are generally kept braced, except ${_} can be
    # simplified when unambiguous and not at EOF.
    nextc = raw_word[end] if end < len(raw_word) else ''
    dq_first = first_double_inner_char(raw_word, end) if end < len(raw_word) else ''
    followed_by_ident = (nextc and is_ident_tail(nextc)) or (dq_first and is_ident_tail(dq_first))
    eof_now = eof and end == len(raw_word)
    if name == '_':
        if followed_by_ident or eof_now or exp.braced and followed_by_ident:
            return '${_}'
        return '$_'
    if name.isdigit() or (name and all(ch.isdigit() for ch in name)):
        if exp.braced:
            return '${%s}' % name
        return '$' + name
    if name in ('@', '-', '*'):
        if exp.braced:
            return '${%s}' % name
        return '$' + ('@' if name == '*' else name)
    if re.match(r'^[A-Za-z_][A-Za-z0-9_]*$', name):
        if followed_by_ident or eof_now:
            return '${%s}' % name
        return '$' + name
    if exp.braced:
        return '${%s}' % name
    return '$' + name


def expansion_needs_quote(exp):
    if exp.kind == 'arith' or exp.kind == 'oldarith' or exp.kind == 'dollarquote':
        return False
    if exp.kind == 'simple' and exp.safe_numeric:
        return False
    if exp.kind == 'param' and (exp.length or exp.indirect or exp.safe_numeric):
        return False
    return True


def transform_arith_inner(inner, old=False):
    # New arithmetic contexts are safe for variables; command substitutions are
    # transformed internally.  The old $[...] form was observed to get normal
    # quoting inside, so use normal word transformation for it.
    if old:
        return transform_fragment_as_words(inner, mode='normal')
    return transform_fragment_as_words(inner, mode='safe')


def transform_double_inner(inner):
    # If the entire double-quoted segment is exactly a simple braced variable,
    # Shellharden removes unnecessary braces for identifier-like variables.
    m = re.fullmatch(r'\$\{([A-Za-z_][A-Za-z0-9_]*|_)\}', inner, re.S)
    if m:
        return '$' + m.group(1)
    # Numbered/special braced parameters remain braced.  Otherwise scan for
    # nested command substitutions/backticks and pitfall variables.
    out = []
    i = 0
    while i < len(inner):
        c = inner[i]
        if c == '\\':
            out.append(inner[i:i+2] if i+1 < len(inner) else c)
            i += 2 if i+1 < len(inner) else 1
            continue
        if c == '`':
            end = consume_backtick(inner, i)
            body = inner[i+1:end-1]
            out.append('$(' + transform_text(body) + ')')
            i = end
            continue
        if c == '$':
            exp = parse_dollar(inner, i)
            if exp:
                if exp.pitfall:
                    raise pitfall_error()
                if exp.kind == 'cmdsub':
                    out.append('$(' + transform_text(exp.content) + ')')
                elif exp.kind == 'arith':
                    out.append('$((' + transform_arith_inner(exp.raw[3:-2], old=False) + '))')
                elif exp.kind == 'oldarith':
                    out.append('$[' + transform_arith_inner(exp.content, old=True) + ']')
                else:
                    out.append(exp.raw)
                i = exp.end
                continue
        out.append(c)
        i += 1
    return ''.join(out)


def pitfall_error():
    return TransformError("Unsupported syntax: Syntactic pitfall", kind="pitfall")


def transform_word(raw, mode='normal', eof=False):
    unsafe = (mode == 'normal')
    if mode in ('heredoc', 'copy'):
        return raw
    out = []
    auto = False

    def close_auto():
        nonlocal auto
        if auto:
            out.append('"')
            auto = False

    def open_auto():
        nonlocal auto
        if not auto:
            out.append('"')
            auto = True

    i = 0
    while i < len(raw):
        c = raw[i]
        if c == "'":
            close_auto()
            end = consume_single_quote(raw, i)
            out.append(raw[i:end])
            i = end
            continue
        if c == '"':
            end = consume_double_quote(raw, i)
            inner = raw[i+1:end-1]
            tin = transform_double_inner(inner)
            if auto:
                # The existing double-quoted segment continues and closes the
                # inserted quote, matching observed output like $x"lit".
                out.append(tin)
                out.append('"')
                auto = False
            else:
                out.append('"' + tin + '"')
            i = end
            continue
        if c == '\\':
            close_auto()
            if i + 1 < len(raw):
                out.append(raw[i:i+2]); i += 2
            else:
                out.append(c); i += 1
            continue
        if c == '`':
            end = consume_backtick(raw, i)
            body = raw[i+1:end-1]
            tbody = transform_text(body)
            if unsafe:
                open_auto(); out.append('$(' + tbody + ')')
            else:
                out.append('`' + tbody + '`')
            i = end
            continue
        if (c == '<' or c == '>') and i + 1 < len(raw) and raw[i+1] == '(':
            close_auto()
            end = consume_process_subst(raw, i)
            body = raw[i+2:end-1]
            out.append(c + '(' + transform_text(body) + ')')
            i = end
            continue
        if c == '$':
            exp = parse_dollar(raw, i)
            if exp:
                if exp.pitfall:
                    raise pitfall_error()
                if exp.kind == 'dollarquote':
                    close_auto(); out.append(exp.raw); i = exp.end; continue
                if exp.kind == 'cmdsub':
                    text = '$(' + transform_text(exp.content) + ')'
                    if unsafe:
                        open_auto(); out.append(text)
                    else:
                        out.append(text)
                    i = exp.end; continue
                if exp.kind == 'arith':
                    close_auto()
                    inner = exp.raw[3:-2]
                    out.append('$((' + transform_arith_inner(inner, old=False) + '))')
                    i = exp.end; continue
                if exp.kind == 'oldarith':
                    close_auto()
                    out.append('$[' + transform_arith_inner(exp.content, old=True) + ']')
                    i = exp.end; continue
                if unsafe and expansion_needs_quote(exp):
                    open_auto()
                    out.append(simple_repr_in_quotes(exp, raw, exp.end, eof=eof))
                else:
                    out.append(exp.raw)
                i = exp.end
                continue
        # ordinary literal character
        if auto:
            close_auto()
        out.append(c)
        i += 1
    close_auto()
    return ''.join(out)


def transform_assignment_value(val):
    if val.startswith('(') and val.endswith(')'):
        return '(' + transform_fragment_as_words(val[1:-1], mode='normal') + ')'
    return transform_word(val, mode='safe')


def transform_assignment_word(w):
    sp = split_assignment(w)
    if not sp:
        return transform_word(w, 'normal')
    lhs, val = sp
    return lhs + transform_assignment_value(val)

# ---------- tokenization and command-aware transformation ----------

@dataclass
class Token:
    typ: str
    raw: str
    start: int
    end: int


def read_word(s, i):
    n = len(s)
    # Arithmetic command (( ... ))
    if s.startswith('((', i):
        j = i + 2
        depth = 0
        while j < n:
            if s[j] in ' \t\r\n' and depth == 0:
                pass
            if s[j] == "'":
                j = consume_single_quote(s, j); continue
            if s[j] == '"':
                j = consume_double_quote(s, j); continue
            if s[j] == '`':
                j = consume_backtick(s, j); continue
            if s[j] == '$' and j + 1 < n:
                if s.startswith('$((', j): j = consume_arith(s, j); continue
                if s.startswith('$(', j): j = consume_dollar_paren(s, j); continue
                if s.startswith('${', j): j = consume_brace(s, j); continue
            if s[j] == '(':
                depth += 1; j += 1; continue
            if s[j] == ')':
                if depth == 0 and j + 1 < n and s[j+1] == ')':
                    return j + 2
                if depth > 0: depth -= 1
                j += 1; continue
            j += 1
        raise TransformError("Unexpected end of file")

    # Group array assignments NAME=( ... ) into one token.
    m = re.match(r'[A-Za-z_][A-Za-z0-9_]*\+?=\(', s[i:])
    if m:
        j = i + m.end()
        depth = 1
        while j < n:
            c = s[j]
            if c == "'": j = consume_single_quote(s, j); continue
            if c == '"': j = consume_double_quote(s, j); continue
            if c == '`': j = consume_backtick(s, j); continue
            if c == '$' and j + 1 < n:
                if s.startswith('$((', j): j = consume_arith(s, j); continue
                if s.startswith('$(', j): j = consume_dollar_paren(s, j); continue
                if s.startswith('${', j): j = consume_brace(s, j); continue
                if s.startswith("$'", j) or s.startswith('$"', j):
                    j = consume_quoted(s, j+1, s[j+1]); continue
            if c == '(':
                depth += 1
            elif c == ')':
                depth -= 1
                if depth == 0:
                    return j + 1
            j += 1
        raise TransformError("Unexpected end of file")

    j = i
    while j < n:
        c = s[j]
        if c in ' \t\r\v\f\n;|&':
            break
        # Redirection separates words at top-level, except process substitution.
        if c in '<>':
            if j == i and j + 1 < n and s[j+1] == '(':
                j = consume_process_subst(s, j); continue
            break
        if c in '()' and j == i:
            break
        if c == "'":
            j = consume_single_quote(s, j); continue
        if c == '"':
            j = consume_double_quote(s, j); continue
        if c == '`':
            j = consume_backtick(s, j); continue
        if c == '\\':
            j += 2 if j + 1 < n else 1; continue
        if c == '$' and j + 1 < n:
            if s.startswith('$((', j): j = consume_arith(s, j); continue
            if s.startswith('$(', j): j = consume_dollar_paren(s, j); continue
            if s.startswith('${', j): j = consume_brace(s, j); continue
            if s.startswith("$'", j) or s.startswith('$"', j):
                j = consume_quoted(s, j+1, s[j+1]); continue
        if (c == '<' or c == '>') and j + 1 < n and s[j+1] == '(':
            j = consume_process_subst(s, j); continue
        j += 1
    return j if j > i else i + 1


def tokenize(s):
    toks = []
    i = 0
    n = len(s)
    prev_sep = True
    while i < n:
        c = s[i]
        st = i
        if c in ' \t\r\v\f':
            while i < n and s[i] in ' \t\r\v\f': i += 1
            toks.append(Token('SPACE', s[st:i], st, i)); continue
        if c == '\n':
            toks.append(Token('OP', c, i, i+1)); i += 1; prev_sep = True; continue
        if c == '#' and (prev_sep or st == 0):
            while i < n and s[i] != '\n': i += 1
            toks.append(Token('COMMENT', s[st:i], st, i)); prev_sep = False; continue
        # redirections (optional fd prefix)
        redir_start = i
        if c.isdigit():
            k = i
            while k < n and s[k].isdigit(): k += 1
            if k < n and s[k] in '<>':
                redir_start = k
            else:
                redir_start = -1
        if (c in '<>' or redir_start >= 0) and not (c in '<>' and i+1 < n and s[i+1] == '('):
            k = redir_start if redir_start >= 0 else i
            op = None
            for candidate in ['<<-', '<<<', '<<', '>>', '>|', '<>', '<&', '>&', '<', '>']:
                if s.startswith(candidate, k):
                    op = candidate; break
            if op:
                end = k + len(op)
                toks.append(Token('REDIR', s[i:end], i, end)); i = end; prev_sep = True; continue
        if s.startswith(';;', i) or s.startswith(';&', i):
            toks.append(Token('OP', s[i:i+2], i, i+2)); i += 2; prev_sep = True; continue
        if s.startswith('&&', i) or s.startswith('||', i):
            toks.append(Token('OP', s[i:i+2], i, i+2)); i += 2; prev_sep = True; continue
        if c in ';|&()':
            toks.append(Token('OP', c, i, i+1)); i += 1; prev_sep = True; continue
        end = read_word(s, i)
        toks.append(Token('WORD', s[i:end], i, end)); i = end; prev_sep = False
    return toks


def transform_fragment_as_words(fragment, mode='normal'):
    toks = tokenize(fragment)
    out = []
    for t in toks:
        if t.typ == 'WORD':
            out.append(transform_word(t.raw, mode=mode, eof=(t.end == len(fragment))))
        else:
            out.append(t.raw)
    return ''.join(out)


def postprocess_tests_and_loops(s):
    # -n/-z simplifications for the first test argument.
    varpat = r'((?:"\$[A-Za-z_][A-Za-z0-9_]*"|"\$[0-9]"|"\$[@*_\-]"|"\$\{[^"\n]+\}"))'
    s = re.sub(r'\btest[ \t]+-n[ \t]+' + varpat, lambda m: 'test ' + m.group(1) + ' != ""', s)
    s = re.sub(r'\btest[ \t]+-z[ \t]+' + varpat, lambda m: 'test ' + m.group(1) + ' = ""', s)
    s = re.sub(r'\[[ \t]+-n[ \t]+' + varpat + r'(?=[ \t]+\])', lambda m: '[ ' + m.group(1) + ' != ""', s)
    s = re.sub(r'\[[ \t]+-z[ \t]+' + varpat + r'(?=[ \t]+\])', lambda m: '[ ' + m.group(1) + ' = ""', s)
    # xyes idiom when x is outside quotes: x"$s" = xyes -> "$s" = yes
    s = re.sub(r'\btest[ \t]+x("\$[A-Za-z_][A-Za-z0-9_]*"|"\$\{[A-Za-z_][A-Za-z0-9_]*\}")[ \t]+([=!]=?)[ \t]+x([^ \t\n;\]]+)',
               lambda m: 'test ' + m.group(1).replace('${','').replace('}','') + ' ' + m.group(2) + ' ' + m.group(3), s)
    s = re.sub(r'\[[ \t]+x("\$[A-Za-z_][A-Za-z0-9_]*"|"\$\{[A-Za-z_][A-Za-z0-9_]*\}")[ \t]+([=!]=?)[ \t]+x([^ \t\n;\]]+)',
               lambda m: '[ ' + m.group(1).replace('${','').replace('}','') + ' ' + m.group(2) + ' ' + m.group(3), s)
    return s


def transform_tokens(s):
    toks = tokenize(s)
    out = []
    cmd_word = 0
    cmd_name = None
    assignment_prefix = True
    redir_next = None
    in_db = False
    case_state = None  # None, selector, need_in, pattern, body
    decl_mode = None
    decl_option_seen = False
    decl_plain_prefix = True

    def reset_cmd():
        nonlocal cmd_word, cmd_name, assignment_prefix, redir_next, decl_mode, decl_option_seen, decl_plain_prefix
        cmd_word = 0; cmd_name = None; assignment_prefix = True; redir_next = None
        decl_mode = None; decl_option_seen = False; decl_plain_prefix = True

    i = 0
    while i < len(toks):
        t = toks[i]
        if t.typ in ('SPACE', 'COMMENT'):
            out.append(t.raw); i += 1; continue
        if t.typ == 'OP':
            out.append(t.raw)
            if t.raw in (';', '\n', '&&', '||', '|', '&'):
                if case_state == 'body' and t.raw == ';;':
                    case_state = 'pattern'
                else:
                    reset_cmd()
            elif t.raw == ';;':
                reset_cmd();
                if case_state == 'body': case_state = 'pattern'
            elif t.raw == ')':
                if case_state == 'pattern':
                    case_state = 'body'; reset_cmd()
            i += 1; continue
        if t.typ == 'REDIR':
            out.append(t.raw)
            redir_next = 'heredoc' if (t.raw.endswith('<<') or t.raw.endswith('<<-')) else 'redir'
            i += 1; continue
        # WORD
        raw = t.raw
        mode = 'normal'
        transformed = None

        if redir_next == 'heredoc':
            mode = 'copy'
        elif in_db:
            mode = 'safe'
        elif case_state in ('selector', 'need_in', 'pattern'):
            mode = 'safe'
        elif raw.startswith('((') and raw.endswith('))'):
            inner = raw[2:-2]
            transformed = '((' + transform_arith_inner(inner, old=False) + '))'
        elif assignment_prefix and is_assignment_word(raw):
            transformed = transform_assignment_word(raw)
        elif decl_mode and is_assignment_word(raw):
            # Observed declare/export/local/readonly leave simple leading
            # assignments alone only before options/bare args; otherwise quote.
            if (not decl_option_seen) and decl_plain_prefix and decl_mode in DECL_BUILTINS:
                transformed = transform_assignment_word(raw)
            else:
                transformed = transform_word(raw, 'normal', eof=(t.end == len(s)))
        else:
            mode = 'normal'

        if transformed is None:
            transformed = transform_word(raw, mode=mode, eof=(t.end == len(s)))
        out.append(transformed)

        # Update parser-ish state after output.
        if redir_next:
            redir_next = None
            # redirection words don't count as command names
            i += 1; continue

        # [[ ... ]] safe sublanguage
        if raw == '[[':
            in_db = True
        elif raw == ']]':
            in_db = False

        # case state machine
        if case_state == 'selector':
            case_state = 'need_in'
        elif case_state == 'need_in' and raw == 'in':
            case_state = 'pattern'
        elif case_state is None and raw == 'case' and cmd_word == 0:
            case_state = 'selector'
        elif raw == 'esac':
            case_state = None

        # Command/declaration state
        if cmd_word == 0 and raw in DECL_BUILTINS:
            decl_mode = raw
        if decl_mode and cmd_word > 0:
            if raw.startswith('-') or raw.startswith('+'):
                decl_option_seen = True
            elif not is_assignment_word(raw):
                decl_plain_prefix = False
        if assignment_prefix and is_assignment_word(raw) and cmd_name is None:
            # still in assignment prefix
            pass
        else:
            if cmd_name is None and raw not in ('[[', ']]'):
                cmd_name = raw
                assignment_prefix = False
            else:
                assignment_prefix = False
        cmd_word += 1
        if raw in SEPARATING_WORDS:
            reset_cmd()
        i += 1
    return ''.join(out)


def transform_text(s):
    masked, repl = mask_heredocs(s)
    out = transform_tokens(masked)
    out = postprocess_tests_and_loops(out)
    out = unmask(out, repl)
    return out

# ---------- highlighting/diff modes ----------


def highlight_word(raw, command=False, assignment=False, db=False):
    if command and raw not in RESERVED and raw not in ('[[', ']]'):
        return CMD_C + raw + RESET
    if raw in RESERVED:
        return KW_C + raw + RESET
    if raw == '[[' or raw == ']]':
        return DBR_C + raw + RESET
    if assignment:
        m = re.match(r'^([A-Za-z_][A-Za-z0-9_]*)(.*)$', raw, re.S)
        if m:
            return ASSIGN_C + m.group(1) + RESET + highlight_word(m.group(2), command=False)
    base_c = DBR_C if db else ''
    base_reset = RESET if db else ''
    out = []
    i = 0
    if db and raw:
        out.append(DBR_C)
    while i < len(raw):
        c = raw[i]
        if c == "'":
            end = consume_single_quote(raw, i)
            if db: out.append(RESET)
            out.append(SQ_C + raw[i:end] + RESET)
            if db: out.append(DBR_C)
            i = end; continue
        if c == '"':
            end = consume_double_quote(raw, i)
            inner = raw[i+1:end-1]
            if db: out.append(RESET)
            out.append(DQ_C + '"')
            out.append(highlight_double_inner(inner))
            out.append(DQ_C + '"' + RESET)
            if db: out.append(DBR_C)
            i = end; continue
        if c == '`':
            end = consume_backtick(raw, i)
            out.append('`' + syntax_highlight(raw[i+1:end-1]) + '`')
            i = end; continue
        if c == '$':
            exp = parse_dollar(raw, i)
            if exp:
                if exp.kind in ('simple','param','array'):
                    if db: out.append(RESET)
                    out.append(VAR_C + exp.raw + RESET)
                    if db: out.append(DBR_C)
                elif exp.kind == 'cmdsub':
                    out.append('$(' + syntax_highlight(exp.content) + ')')
                else:
                    out.append(exp.raw)
                i = exp.end; continue
        out.append(c)
        i += 1
    if db and raw:
        out.append(RESET)
    return ''.join(out)


def highlight_double_inner(inner):
    out = []
    i = 0
    while i < len(inner):
        if inner[i] == '\\':
            out.append(DQ_C + (inner[i:i+2] if i+1 < len(inner) else inner[i]))
            i += 2 if i+1 < len(inner) else 1; continue
        if inner[i] == '$':
            exp = parse_dollar(inner, i)
            if exp:
                if exp.kind in ('simple','param','array'):
                    out.append(VAR_C + exp.raw + DQ_C)
                elif exp.kind == 'cmdsub':
                    out.append('$(' + syntax_highlight(exp.content) + DQ_C + ')')
                else:
                    out.append(exp.raw)
                i = exp.end; continue
        if inner[i] == '`':
            end = consume_backtick(inner, i)
            out.append('`' + syntax_highlight(inner[i+1:end-1]) + DQ_C + '`')
            i = end; continue
        out.append(inner[i])
        i += 1
    return ''.join(out)


def syntax_highlight(s):
    try:
        toks = tokenize(s)
    except TransformError:
        return s
    out = []
    cmd_word = 0
    assignment_prefix = True
    in_db = False
    for t in toks:
        if t.typ == 'SPACE' or t.typ == 'OP' or t.typ == 'REDIR':
            out.append(t.raw)
            if t.typ == 'OP' and t.raw in (';', '\n', '&&', '||', '|', '&'):
                cmd_word = 0; assignment_prefix = True
            continue
        if t.typ == 'COMMENT':
            out.append(COMMENT_C + t.raw + RESET); continue
        raw = t.raw
        if raw == '[[':
            in_db = True
            out.append(DBR_C + raw + RESET)
        elif raw == ']]':
            out.append(DBR_C + raw + RESET)
            in_db = False
        elif raw in RESERVED:
            out.append(KW_C + raw + RESET)
            if raw in SEPARATING_WORDS:
                cmd_word = 0; assignment_prefix = True
        elif assignment_prefix and is_assignment_word(raw):
            out.append(highlight_word(raw, assignment=True))
        elif cmd_word == 0:
            out.append(highlight_word(raw, command=True, db=in_db))
            assignment_prefix = False
        else:
            out.append(highlight_word(raw, db=in_db))
            assignment_prefix = False
        cmd_word += 1
    return ''.join(out)


def colored_diff(orig, trans, syntax=False):
    sm = difflib.SequenceMatcher(a=orig, b=trans, autojunk=False)
    opcodes = sm.get_opcodes()
    parts = []
    for idx, (tag, i1, i2, j1, j2) in enumerate(opcodes):
        if tag == 'equal':
            seg = orig[i1:i2]
            parts.append(syntax_highlight(seg) if syntax else seg)
        elif tag == 'delete':
            parts.append(RED_BG + orig[i1:i2] + RESET)
        elif tag == 'insert':
            ins = trans[j1:j2]
            if syntax:
                # If immediately followed by a syntax-colored equal segment,
                # the next color code itself resets the green background, just
                # like the observed syntax-suggest output.  Otherwise reset now.
                need_reset = True
                if idx + 1 < len(opcodes) and opcodes[idx+1][0] == 'equal':
                    nxt = orig[opcodes[idx+1][1]:opcodes[idx+1][2]]
                    if syntax_highlight(nxt).startswith('\x1b['):
                        need_reset = False
                parts.append(GREEN + ins + (RESET if need_reset else ''))
            else:
                parts.append(GREEN + ins + RESET)
        elif tag == 'replace':
            parts.append(RED_BG + orig[i1:i2] + RESET)
            ins = trans[j1:j2]
            parts.append(GREEN + ins + RESET)
    return ''.join(parts)

# ---------- CLI ----------


def error_text(prefix, err, source=''):
    if getattr(err, 'kind', '') == 'pitfall':
        return (f"{prefix}: Unsupported syntax: Syntactic pitfall\n"
                "This does not mean what it looks like. You may be forgiven to think that the full string of numerals is the variable name. Only the fist is.\n\n"
                "Try this and be shocked: f() { echo \"$9\" \"$10\"; }; f a b c d e f g h i j\n\n"
                "Here is where braces should be used to disambiguate, e.g. \"${10}\" vs \"${1}0\".\n\n"
                "Syntactic pitfalls are deemed too dangerous to fix automatically\n"
                "(the purpose of Shellharden is to fix vulnerable code – code that mostly does what it looks like, as opposed to code that never does what it looks like):\n"
                "* Fixing what it does would be 100% subtle and might slip through code review unnoticed.\n"
                "* Fixing its look would make a likely bug look intentional.\n")
    return (f"{prefix}: Unexpected end of file\n"
            "The file's end was reached without closing all sytactic scopes.\n"
            "Either, the parser got lost, or the file is truncated or malformed.\n")


def process_data(text, mode):
    trans = transform_text(text)
    if mode == 'transform' or mode == 'replace' or mode == 'check':
        return trans
    if mode == 'suggest':
        return colored_diff(text, trans, syntax=False)
    if mode == 'syntax':
        return syntax_highlight(text)
    # syntax-suggest default
    return colored_diff(text, trans, syntax=True)


def main(argv):
    mode = 'syntax-suggest'
    files = []
    parse_opts = True
    for arg in argv[1:]:
        if parse_opts and arg == '--':
            parse_opts = False; continue
        if parse_opts and arg.startswith('-') and arg != '':
            if arg in ('-h', '--help'):
                sys.stdout.write(HELP); return 0
            if arg == '--version':
                sys.stdout.write(VERSION + '\n'); return 0
            if arg == '--suggest': mode = 'suggest'; continue
            if arg == '--syntax': mode = 'syntax'; continue
            if arg == '--syntax-suggest': mode = 'syntax-suggest'; continue
            if arg == '--transform': mode = 'transform'; continue
            if arg == '--check': mode = 'check'; continue
            if arg == '--replace': mode = 'replace'; continue
            sys.stderr.write(f"{arg}: No such option.\n"); return 3
        files.append(arg)

    # No arguments means no input is read.
    exit_error = False
    changed = False
    outputs = []

    if not files:
        return 0

    for path in files:
        if path == '':
            data = sys.stdin.buffer.read()
            text = data.decode('latin-1')
            prefix = ''
        else:
            try:
                with open(path, 'rb') as f:
                    data = f.read()
            except OSError as e:
                sys.stderr.write(f"{path}: {e.strerror} (os error {e.errno})\n")
                exit_error = True
                continue
            text = data.decode('latin-1')
            prefix = path
        try:
            trans = transform_text(text)
            if trans != text:
                changed = True
            if mode == 'check':
                continue
            if mode == 'replace':
                if path != '':
                    with open(path, 'wb') as f:
                        f.write(trans.encode('latin-1'))
                continue
            if mode == 'transform':
                out = trans
            elif mode == 'suggest':
                out = colored_diff(text, trans, syntax=False)
            elif mode == 'syntax':
                out = syntax_highlight(text)
            else:
                out = colored_diff(text, trans, syntax=True)
            outputs.append(out)
        except TransformError as e:
            # The original streams partial output before reporting.  Here we
            # report the same class of failure and mark the command failed.
            sys.stderr.write(error_text(prefix, e, text))
            exit_error = True
            continue

    if mode not in ('check', 'replace'):
        sys.stdout.buffer.write(''.join(outputs).encode('latin-1'))
    if mode == 'check' and changed:
        return 2
    if changed and mode == 'check':
        return 2
    if mode == 'check' and exit_error and changed:
        return 2
    if mode == 'check' and changed:
        return 2
    # Observed precedence: --check returns 2 if any change was found, even if
    # another file was missing.
    if mode == 'check' and changed:
        return 2
    if mode == 'check':
        return 2 if changed else (1 if exit_error else 0)
    return 1 if exit_error else 0

if __name__ == '__main__':
    sys.exit(main(sys.argv))
